import std.io
import std.string

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let r = string.runeFrom(string.runeCode('中'))
    io.println("${r}")
    let s = string.runeFrom(97)
    if string.runeCode(s) == 97 { io.println("rt-ok") } else { io.println("rt-bad") }
    return Ok(())
}
